# DK GRD.  Gram - Rødding
#
let gr = path("d3.dk.grd");

with detail = 4, railway = :first :g1000 :pax :removed {
    # point.dk.Gram  dk.HVA

    with link = "line.dk.GRD" {
        track(gr[:gra.yr, :gra.yr + 0.76km]);
        line_label(:left:e, gr[:gra.yr + 0.75km] << 0.5lt,
            (0dt, -0.2dt), "GRD"
        );
        track(gr[:gra.yr + 0.74km, :las - 0.49sw]);
    }

    with link = "point.dk.Låsled" {
        track(gr[:las - 0.5sw, :las + 0.5sw]);
        marker(:right :de.hp, gr[:las] >> 0.5lt);
        station(:right, gr[:las] >> 0.5lt >> 1sh + (1.5dt, 1.2dt),
            span(:former, "Laasled"),
            "Låsled",
            "GRD: 43,1"
        );
    }

    with link = "line.dk.GRD" {
        track(gr[:las + 0.49sw, :bra - 0.49sw]);
    }

    with link = "point.dk.Brændstrup" {
        track(gr[:bra - 0.5sw, :bra + 0.5sw]);
        marker(:right :de.bf, gr[:bra] >> 0.5lt);
        station(:right, gr[:bra] >> 0.5lt >> 1sh + (1.5dt, 1.2dt),
            span(:former, "Brendstrup"),
            "Brændstrup",
            "GRD: 45,3"
        );
    }

    with link = "line.dk.GRD" {
        track(gr[:bra + 0.49sw, :bra + 3.01km]);
        line_label(:left:e, gr[:bra + 3km] << 0.5lt, (0dt, 0.1dt), "GRD");
        track(gr[:bra + 2.99km, :rod - 0.49sw]);
    }

    with link = "point.dk.Rødding" {
        track(gr[:rod - 0.5sw, :rod.f]);
        marker(:right :de.bf, gr[:rod] >> 0.7lt);
        station(:top, gr[:rod] << 0.5lt << 1.5dt,
            span(:former, "Rödding"),
            span(:bold, "Rødding"),
            "GRD: 49,7"
        );
    }
}

